   new  retailer_category  for  the  period  jan-mar

SELECT   skui.status_retailer_id  AS  retailer_id,   sp.categories  as  category_id,   cat.name  as  category,     SUM(       CASE           WHEN  sqpm.box_calculation_uom  IS  NOT  NULL                AND  sqpm.box_calculation_uom  >  0               THEN  sqpm.box_calculation_uom             WHEN  sqpm.box_calculation_uom  IS  NULL                OR  sqpm.box_calculation_uom  =  0               THEN  CASE                       WHEN  skui.uom  =  'B5'  THEN  0.5                       ELSE  1                    END       END   )  AS  total_box_count    FROM  sku_inventories  skui  join  sku_products  sp  on  sp.id  =  skui.product_id  left  join  master_categories  cat  on  cat.id  =  sp.categories  join  users  on  users.id  =  skui.status_retailer_id  left  JOIN  sku_qr_points_maps  sqpm       ON  sqpm.sku_code  =  skui.sku_code       AND  sqpm.uom  =  skui.uom  
  where  retailer_scanned_at  between  '2025-04-01  00:00:00'  and  '2025-12-31  23:59:59'  and  users.created_at  <  '2026-01-01'    GROUP  BY   skui.status_retailer_id,   sp.categories,   cat.name  )  as  rjan  on  rjan.retailer_id  =  rcsfeb.retailer_id  and  rjan.category_id  =  rcsfeb.category_id    where  (rjan.total_box_count  <  5  OR  rjan.total_box_count  IS  NULL)  and  rc+sfeb.total_box_count  >=5;    

