and  uom  =  'B5'  and  retailer_scanned_at  >=  '2026-04-01'  and  retailer_scanned_at  <  '2026-04-17';    select  *  from  sku_inventories  where  status_retailer_id  =  75086  and  uom  in  ('B5','B10');   
