         WHEN  dqwt.reference_type  IN  ('credit_note')   --  abs           THEN  dqwt.amount           ELSE  0       END   )  )AS  credit_note     FROM  deactivated_qr_wallet_transactions  dqwt    JOIN  users  u   ON  u.id  =  dqwt.user_id    LEFT  JOIN  sku_inventories  si   ON  si.id  =  dqwt.reference_id    LEFT  JOIN  sku_products  sp   ON  sp.id  =  si.product_id    WHERE  dqwt.created_at  <  '2026-04-01'  AND  u.user_role  =  4   GROUP  BY  u.distributer_id;  
