SELECT       sd.*,       --  ✅  final  week  label      CASE           WHEN  sd.week_number  =  1  THEN  'Week  1'          WHEN  sd.week_number  =  2  THEN  'Week  2'          WHEN  sd.week_number  =  3  THEN  'Week  3'          WHEN  sd.week_number  =  4  THEN  'Week  4'          ELSE  'Week  5'      END  AS  scan_week,       ui.customer_name,       ui.city,       ui.pincode,       ui.state,   
    ui.zone,       ui.actual_city,       COALESCE(bs.scan_type,  'Cash  Point  Scan')  AS  scan_type,      bs.scheme_name,      bs.earned_units,       mp.points  AS  earned_point   FROM  scan_data  sd   LEFT  JOIN  user_info  ui       ON  ui.id  =  sd.customer_id   LEFT  JOIN  box_scans  bs       ON  bs.skui_id  =  sd.id   LEFT  JOIN  mypoints  mp       ON  mp.sku_inventory_id  =  sd.id     AND  mp.users_id  =  sd.customer_id   WHERE  sd.sap_code  =  'D12IND2101';    
