SELECT    si.distributer_id,   si.id,   u.`name`,      si.sku_code,      si.lpn_number,      si.uom,      si.status_retailer_id,      si.retailer_scanned_at,      si.created_at,      'Retailer'  as  role_name,      sqpm.gride_type,      sqpm.box_calculation_uom,     sp.product_name,      COALESCE(wt.amount,  0)  AS  Earned_Units,  
    sqpm.pcs_calculation_uom,      csg.name   FROM  sku_inventories  si   JOIN  users  u       ON  u.id  =  si.status_retailer_id  JOIN  sku_products  sp       ON  sp.id  =  si.product_id  LEFT  JOIN  sku_qr_points_maps  sqpm       ON  si.sku_code  =  sqpm.sku_code  and  sqpm.uom  =  si.uom   join  category_sub_groups  csg  on   csg.id  =  sp.category_sub_group_id        JOIN  scheme_wallet_transactions  wt          ON  si.id  =  wt.reference_id  and  wt.reference_type  =  'sku_scan'     and  scheme_id  =  3  WHERE  u.user_role  =  2;        
